from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class AlarmInfoFMV1(SchemaObject):
    sequence_number = SchemaField(name="sequence_number", not_null=True)
    severity = SchemaField(name="severity", not_null=True)
    fault_id = SchemaField(name="fault_id", not_null=True)
    fault_name = SchemaField(name="fault_name", not_null=True)
    fault_visibility = SchemaField(name="fault_visibility", not_null=True)
    fault_state = SchemaField(name="fault_state", not_null=True)
    reported_alarm_id = SchemaField(name="reported_alarm_id", not_null=True)
    reported_alarm_name = SchemaField(name="reported_alarm_name", not_null=True)
    time_started = SchemaField(name="time_started", not_null=True)
    time_cleared = SchemaField(name="time_cleared", optional=True)
    source_object = SchemaField(name="source_object", not_null=True)
    source_uid = SchemaField(name="source_uid", not_null=True)

    def __init__(self, sequence_number=None, severity=None, fault_id=None, fault_name=None, fault_visibility=None,
                 fault_state=None, reported_alarm_id=None, reported_alarm_name=None, time_started=None,
                 time_cleared=None, source_object=None, source_uid=None):
        self.sequence_number = sequence_number
        self.severity = severity
        self.fault_id = fault_id
        self.fault_name = fault_name
        self.fault_visibility = fault_visibility
        self.fault_state = fault_state
        self.reported_alarm_id = reported_alarm_id
        self.reported_alarm_name = reported_alarm_name
        self.time_started = time_started.strftime("%Y-%m-%dT%H:%M:%S%Z") if time_started else time_started
        self.time_cleared = time_cleared.strftime("%Y-%m-%dT%H:%M:%S%Z") if time_cleared else time_cleared
        self.source_object = source_object
        self.source_uid = source_uid
        super(AlarmInfoFMV1, self).__init__()
